<?php
require_once __DIR__ . '/assets/php/bootstrap.php';
$slug = trim((string) ($_GET['artista'] ?? ''));
$artist = null; $albums = []; $posts = [];
if (preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/', $slug)) {
    $s = db()->query('SELECT id_artista,nombre,biografia,imagen,genero FROM artista WHERE activo=TRUE');
    foreach ($s->fetchAll() as $candidate) { if (artist_slug($candidate['nombre']) === $slug) { $artist = $candidate; break; } }
    if ($artist) {
        $s = db()->prepare('SELECT id_album,titulo,fecha_lanzamiento,portada,tipo FROM album WHERE artista_id=:id ORDER BY fecha_lanzamiento DESC,titulo');
        $s->execute(['id' => $artist['id_artista']]); $albums = $s->fetchAll();
        $s = db()->prepare("SELECT b.titulo,b.`desc`,b.img,b.slug,d.fecha_publicacion FROM blog b JOIN blog_detalle d ON d.blog_id=b.id_blog JOIN blog_artista ba ON ba.blog_id=b.id_blog WHERE ba.artista_id=:id AND d.estado='publicado' AND d.fecha_publicacion IS NOT NULL AND d.fecha_publicacion<=NOW() ORDER BY d.fecha_publicacion DESC");
        $s->execute(['id' => $artist['id_artista']]); $posts = $s->fetchAll();
    }
}
if (!$artist) http_response_code(404);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($artist['nombre'] ?? 'Artista no disponible')?> — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/home.css"><link rel="stylesheet" href="assets/css/artists.css?v=3"><link rel="stylesheet" href="assets/css/posts.css"></head><body><header class="site-header"><div class="container header-inner"><a class="brand" href="index.php">SIDE B<span class="brand-dot">.</span></a><nav class="primary-nav"><a class="nav-link" href="index.php">Inicio</a><a class="nav-link is-active" href="artistas.php">Artistas</a><a class="nav-link" href="tienda.php">Tienda</a></nav><?=logout_control()?></div></header><main id="contenido" class="artist-profile"><?php if(!$artist):?><div class="container"><p class="profile-note">El artista no está disponible.</p></div><?php else:?><div class="container artist-profile-hero"><div class="artist-profile-copy"><p class="eyebrow"><?=e($artist['genero'] ?: 'Artista SIDE B')?></p><h1><?=e($artist['nombre'])?></h1><?php if($artist['biografia']):?><p><?=nl2br(e($artist['biografia']))?></p><?php else:?><p>Próximamente encontrarás más información sobre este artista.</p><?php endif;?></div><div class="artist-profile-art visual-surface visual-surface--artist"><?php if($artist['imagen']):?><img src="<?=e($artist['imagen'])?>" alt="<?=e($artist['nombre'])?>"><?php endif;?></div></div><section class="container artist-work"><p class="eyebrow">En SIDE B</p><h2>Historias y lanzamientos</h2><?php if(!$posts && !$albums):?><p class="profile-note">Aún no hay publicaciones ni álbumes asociados a este artista.</p><?php endif;?><?php if($posts):?><div class="editorial-grid"><?php foreach($posts as $post):?><article class="story-card"><a class="story-image visual-surface visual-surface--olive" href="publicacion.php?slug=<?=rawurlencode($post['slug'])?>"><?php if($image=publication_image_url($post['img'])):?><img src="<?=e($image)?>" alt=""><?php endif;?></a><div class="story-content"><p class="card-kicker">Publicación</p><h3><a href="publicacion.php?slug=<?=rawurlencode($post['slug'])?>"><?=e($post['titulo'])?></a></h3><?php if($post['desc']):?><p class="card-excerpt"><?=e($post['desc'])?></p><?php endif;?></div></article><?php endforeach;?></div><?php endif;?><?php if($albums):?><div class="artist-albums"><?php foreach($albums as $album):?><article><div><?php if($album['portada']):?><img src="<?=e($album['portada'])?>" alt=""><?php endif;?></div><p class="card-kicker"><?=e($album['tipo'])?></p><h3><?=e($album['titulo'])?></h3><?php if($album['fecha_lanzamiento']):?><small><?=e($album['fecha_lanzamiento'])?></small><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><?php endif;?></main><?=sideb_footer()?></body></html>
